    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());
        char[] s = reader.readLine().trim().toCharArray();
        String[] tokens = reader.readLine().trim().split("\\s");
        int[] beauty = new int[n];
        int totalSum = 0;
        for (int i = 0; i < n; i++) {
            beauty[i] = Integer.parseInt(tokens[i]);
            totalSum += beauty[i];
        }
        int mismatchCount = 0;
        int[] freqCount = new int[26];
        int sumOfPairs = 0;
        for (int i = 0; i < n / 2; i++) {
            if (s[i] == s[n - i - 1]) {
                mismatchCount++;
                freqCount[s[i] - 'a']++;
                sumOfPairs += Math.min(beauty[i], beauty[n - i - 1]);
            }
        }
        int maxFreqVal = 0;
        int maxCharIdx = 0;
        for (int i = 0; i < 26; i++) {
            if (freqCount[i] > maxFreqVal) {
                maxFreqVal = freqCount[i];
                maxCharIdx = i;
            }
        }
        if (2 * maxFreqVal <= mismatchCount) {
            System.out.println(totalSum);
            return;
        }
        List<Integer> candidates = new ArrayList<>();
