                candidates.add(Math.min(beauty[i], beauty[n - i - 1]));
            }
        }
        Collections.sort(candidates);
        int removeCount = 2 * maxFreqVal - mismatchCount;
        for (int i = 0; i < removeCount; i++) {
            totalSum -= candidates.get(i);
        }
        System.out.println(totalSum);
    }
}
