    string s;
    cin >> s;
    vector<int> beauty(n);
    int totalSum = 0;
    for (int i = 0; i < n; i++) {
        cin >> beauty[i];
        totalSum += beauty[i];
    }
    int mismatchCount = 0;
    vector<int> freqCount(26, 0);
    int sumOfPairs = 0;
    for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - i - 1]) {
            mismatchCount++;
            freqCount[s[i] - 'a']++;
            sumOfPairs += min(beauty[i], beauty[n - i - 1]);
        }
    }
    int maxFreqVal = 0;
    int maxCharIdx = 0;
    for (int i = 0; i < 26; i++) {
        if (freqCount[i] > maxFreqVal) {
            maxFreqVal = freqCount[i];
            maxCharIdx = i;
        }
    }
    if (2 * maxFreqVal <= mismatchCount) {
        cout << totalSum << "\n";
        return 0;
    }
    vector<int> candidates;
    for (int i = 0; i < n / 2; i++) {
        if ((s[i] - 'a') != maxCharIdx && (s[n - i - 1] - 'a') != maxCharIdx && s[i] != s[n - i - 1]) {
